private void queue_reload(final boolean start, final String reason) {
  final boolean doStop = started;
  final boolean doStart = (start && isEnabled() && networkState.isSuitable());
  EntityLog.log(this, "Queue reload" + " doStop=" + doStop + " doStart=" + doStart + " queued=" + queued + " " + reason);
  started = doStart;
  queued++;
  try {
    queue.submit(new Runnable() {
      PowerManager pm = (PowerManager) getSystemService(Context.POWER_SERVICE);
      PowerManager.WakeLock wl = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, BuildConfig.APPLICATION_ID + ":manage");
      @Override
      public void run() {
        DB db = DB.getInstance(ServiceSynchronize.this);
        try {
          wl.acquire();
          EntityLog.log(ServiceSynchronize.this, "Reload" + " stop=" + doStop + " start=" + doStart + " queued=" + queued + " " + reason);
          if (doStop) stop();
          if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            NotificationManager nm = (NotificationManager) getSystemService(Context.NOTIFICATION_SERVICE);
            for (EntityAccount account : db.account().getAccountsTbd()) nm.deleteNotificationChannel(EntityAccount.getNotificationChannelId(account.id));
          }
          int accounts = db.account().deleteAccountsTbd();
          int identities = db.identity().deleteIdentitiesTbd();
          if (accounts > 0 || identities > 0) Log.i("Deleted accounts=" + accounts + " identities=" + identities);
          if (doStart) start();
        } catch (Throwable ex) {
          Log.e(ex);
        } finally {
          queued--;
          EntityLog.log(ServiceSynchronize.this, "Reload done queued=" + queued);
          if (queued == 0 && !isEnabled()) {
            try {
              Thread.sleep(STOP_DELAY);
            } catch (InterruptedException ignored) {
            }
            if (queued == 0 && !isEnabled()) stopService();
          }
          wl.release();
        }
      }
    });
  } catch (RejectedExecutionException e) {
    Log.e("Task submission rejected: " + e.getMessage());
  }
}
